    public static string T(string text){if(text==null)return "";string prefix="Данные устарели • последнее обновление";if(text.StartsWith(prefix+" "))return T(prefix)+text.Substring(prefix.Length);string[] row;return Strings.TryGetValue(text,out row)?row[Array.IndexOf(Codes,Code)]:text;}
    public static void Menu(ItemsControl menu){foreach(var item in menu.Items.OfType<MenuItem>()){var header=item.Header as string;if(header!=null)item.Header=T(header);var tip=item.ToolTip as string;if(tip!=null)item.ToolTip=T(tip);if(item.HasItems)Menu(item);}}
    public static string Line(string text){
        if(string.IsNullOrEmpty(text))return text;
        foreach(string key in new[]{"Доступно сбросов","Обновлено","Сброс","До сброса","Через"})if(text.StartsWith(key+":"))return T(key)+text.Substring(key.Length);
        return T(text).Replace(": осталось ",": "+T("Осталось")+" ");
    }
